<?php

/**
 * The services (services/<service>) and shared libraries (libs/<lib>) that live in their own folder are part of this
 * application as well: their classes keep their namespaces, so every other class finds them unchanged. This file
 *   - defines the aliases @services and @libs,
 *   - registers their class maps (services/<service>/backend/classmap.php, libs/<lib>/classmap.php; generated by
 *     `php yii service/pack --all`),
 *   - returns the admin view folders of their dashboards, which are mapped over app/modules/admin/views by the theme.
 *
 * @return array ['views' => path map for the view theme]
 */
$repo = dirname(__DIR__, 2);
Yii::setAlias('@services', $repo . '/services');
Yii::setAlias('@libs', $repo . '/libs');
Yii::setAlias('@customer', $repo . '/customer');

$classes = [];
foreach (array_merge(glob($repo . '/services/*/backend/classmap.php') ?: [], glob($repo . '/libs/*/classmap.php') ?: [], glob($repo . '/customer/backend/classmap.php') ?: []) as $file) {
    $classes += require $file;
}
Yii::$classMap = $classes + Yii::$classMap;

$views = [];
foreach (array_merge(glob($repo . '/services/*/partner-dashboard/views/*', GLOB_ONLYDIR) ?: [], glob($repo . '/libs/*/dashboard/views/*', GLOB_ONLYDIR) ?: [], glob($repo . '/customer/dashboard/views/*', GLOB_ONLYDIR) ?: []) as $dir) {
    $views['@app/modules/admin/views/' . basename($dir)] = [$dir];
}

return ['views' => $views];
